with kept_keys as (select category from products intersect all select category from products where cost > 510), kept_rows as (select s.* from products s inner join kept_keys k on s.category = k.category) select case when cost >= 650 then 'HIGH' else 'LOW' end as cost_tier, approx_percentile(price, 0.95) as price_p95, count(distinct category) as distinct_categories, bit_and(stock_qty) as stock_qty_bit_and from kept_rows group by case when cost >= 650 then 'HIGH' else 'LOW' end order by price_p95 nulls last;
